package eval

func moderationWorkflowSuite() Suite {
	base := rngLedgerSuite()
	firstOpen := map[string]any{"report_id": "report-1", "target_id": "event-1", "reason": "spam", "status": "open", "reporter": "player-a", "sequence": 1}
	secondOpen := map[string]any{"report_id": "report-2", "target_id": "event-2", "reason": "abuse", "status": "open", "reporter": "dm", "sequence": 2}
	firstResolved := map[string]any{"report_id": "report-1", "target_id": "event-1", "reason": "spam", "status": "resolved", "reporter": "player-a", "sequence": 1, "action": "remove", "note": "Removed duplicate spam event.", "resolver": "dm"}
	finalReports := map[string]any{"reports": []any{firstResolved, secondOpen}}
	return Suite{ID: "093-moderation-workflow", Name: "Campaign Play 093: Moderation Workflow", Tests: append(base.Tests,
		playTest("play-moderation-create-campaign", "DM creates a fresh campaign for moderation workflow", "POST", "/v1/play/campaigns", map[string]any{"id": "play-093", "name": "Moderation Game", "max_players": 2}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"id": "play-093", "name": "Moderation Game", "owner": "dm", "status": "lobby", "max_players": 2}),
		playTest("play-moderation-join-player-a", "Player A joins the moderation campaign", "POST", "/v1/play/campaigns/play-093/members", map[string]any{"character_id": "play-093-char-a", "name": "Mira", "class": "wizard"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"username": "player-a", "character_id": "play-093-char-a", "name": "Mira", "class": "wizard"}),
		playTest("play-moderation-list-unauthenticated", "Unauthenticated report listing is rejected", "GET", "/v1/play/campaigns/play-093/moderation/reports", nil, nil, 401, nil),
		playTest("play-moderation-list-nonmember-forbidden", "Non-members cannot list moderation reports", "GET", "/v1/play/campaigns/play-093/moderation/reports", nil, map[string]string{"Authorization": "Bearer session-stranger"}, 403, nil),
		playTest("play-moderation-create-invalid-empty-report-id", "Reports require a nonempty report ID", "POST", "/v1/play/campaigns/play-093/moderation/reports", map[string]any{"report_id": "", "target_id": "event-0", "reason": "spam"}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-moderation-create-invalid-empty-target-id", "Reports require a nonempty target ID", "POST", "/v1/play/campaigns/play-093/moderation/reports", map[string]any{"report_id": "bad-report", "target_id": "", "reason": "spam"}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-moderation-create-invalid-empty-reason", "Reports require nonempty report ID target and reason", "POST", "/v1/play/campaigns/play-093/moderation/reports", map[string]any{"report_id": "bad-report", "target_id": "event-0", "reason": ""}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTestExactJSON("play-moderation-create-player", "Player submits the first exact moderation report", "POST", "/v1/play/campaigns/play-093/moderation/reports", map[string]any{"report_id": "report-1", "target_id": "event-1", "reason": "spam"}, map[string]string{"Authorization": playerAAuth}, 201, firstOpen),
		playTestExactJSON("play-moderation-create-dm", "DM can also submit a moderation report", "POST", "/v1/play/campaigns/play-093/moderation/reports", map[string]any{"report_id": "report-2", "target_id": "event-2", "reason": "abuse"}, map[string]string{"Authorization": dmAuth}, 201, secondOpen),
		playTest("play-moderation-duplicate-conflict", "Duplicate report IDs are rejected without appending", "POST", "/v1/play/campaigns/play-093/moderation/reports", map[string]any{"report_id": "report-1", "target_id": "event-mutated", "reason": "other"}, map[string]string{"Authorization": playerAAuth}, 409, nil),
		playTestExactJSON("play-moderation-list-after-duplicate", "Reports remain ordered and immutable after duplicate rejection", "GET", "/v1/play/campaigns/play-093/moderation/reports", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"reports": []any{firstOpen, secondOpen}}),
		playTest("play-moderation-resolution-player-forbidden", "Players cannot resolve moderation reports", "PUT", "/v1/play/campaigns/play-093/moderation/reports/report-1/resolution", map[string]any{"action": "allow", "note": "Looks fine."}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-moderation-resolution-unknown", "DM resolving an unknown report returns 404", "PUT", "/v1/play/campaigns/play-093/moderation/reports/missing-report/resolution", map[string]any{"action": "allow", "note": "No matching report."}, map[string]string{"Authorization": dmAuth}, 404, nil),
		playTest("play-moderation-resolution-invalid-action", "Resolution action must be allow or remove", "PUT", "/v1/play/campaigns/play-093/moderation/reports/report-1/resolution", map[string]any{"action": "delete", "note": "Wrong action."}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-moderation-resolution-empty-note", "Resolution note must be nonempty", "PUT", "/v1/play/campaigns/play-093/moderation/reports/report-1/resolution", map[string]any{"action": "remove", "note": ""}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-moderation-resolution-remove", "DM resolves an open report exactly once", "PUT", "/v1/play/campaigns/play-093/moderation/reports/report-1/resolution", map[string]any{"action": "remove", "note": "Removed duplicate spam event."}, map[string]string{"Authorization": dmAuth}, 200, firstResolved),
		playTest("play-moderation-resolution-repeat-conflict", "Resolved reports reject a second resolution without mutation", "PUT", "/v1/play/campaigns/play-093/moderation/reports/report-1/resolution", map[string]any{"action": "allow", "note": "Trying to mutate after resolution."}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-moderation-list-after-repeat-conflict", "Final moderation report state is stable after repeat conflict", "GET", "/v1/play/campaigns/play-093/moderation/reports", nil, map[string]string{"Authorization": dmAuth}, 200, finalReports),
	)}
}
